/* Orchard — Shared Styles */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --dark: #1d1d1f;
  --light-bg: #f5f5f7;
  --secondary: #6e6e73;
  --blue: #0066cc;
  --blue-hover: #004499;
  --white: #ffffff;
  --border: #d2d2d7;
  --card-radius: 18px;
  --font: -apple-system, "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--dark); background: var(--white); -webkit-font-smoothing: antialiased; }

a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; color: var(--blue-hover); }

/* Ribbon Banner */
.ribbon-banner {
  background: var(--light-bg);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  color: var(--dark);
  border-bottom: 1px solid var(--border);
}
.ribbon-banner a { color: var(--blue); font-weight: 400; }

/* Global Nav */
.global-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border);
}
.global-nav-inner {
  max-width: 980px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 44px;
  padding: 0 16px;
  gap: 0;
}
.nav-logo { font-size: 20px; font-weight: 300; letter-spacing: -0.5px; color: var(--dark); flex: 0 0 auto; margin-right: auto; }
.nav-logo span { font-weight: 600; }
.nav-links { display: flex; gap: 4px; list-style: none; align-items: center; margin: 0 auto; }
.nav-links a { font-size: 13px; color: var(--dark); padding: 4px 8px; border-radius: 6px; transition: background 0.15s; white-space: nowrap; }
.nav-links a:hover { background: var(--light-bg); text-decoration: none; }
.nav-links a.active { font-weight: 600; }
.nav-actions { display: flex; gap: 8px; align-items: center; margin-left: auto; }
.nav-actions a { font-size: 13px; color: var(--dark); }

/* Section */
.section { padding: 60px 22px; max-width: 1200px; margin: 0 auto; }
.section-sm { padding: 40px 22px; max-width: 1200px; margin: 0 auto; }

.section-header { margin-bottom: 32px; }
.section-header h2 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; color: var(--dark); line-height: 1.1; }
.section-header p { font-size: 17px; color: var(--secondary); margin-top: 6px; }

/* Carousel */
.carousel-wrapper { position: relative; }
.carousel-track-outer { overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 16px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 50%;
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  z-index: 10;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  transition: box-shadow 0.15s, background 0.15s;
  color: var(--dark);
}
.carousel-btn:hover { background: var(--light-bg); box-shadow: 0 4px 16px rgba(0,0,0,0.16); }
.carousel-btn.prev { left: -20px; }
.carousel-btn.next { right: -20px; }
.carousel-btn svg { width: 16px; height: 16px; pointer-events: none; }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }

/* Product Card (carousel) */
.product-card {
  flex: 0 0 220px;
  background: var(--light-bg);
  border-radius: var(--card-radius);
  padding: 24px 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 320px;
  position: relative;
  transition: box-shadow 0.2s;
}
.product-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.1); }
.product-card-img { height: 140px; display: flex; align-items: center; justify-content: center; margin-bottom: 8px; }
.product-card-img img { max-height: 130px; max-width: 100%; object-fit: contain; }
.badge { display: inline-block; background: var(--blue); color: #fff; font-size: 10px; font-weight: 700; letter-spacing: 0.5px; padding: 2px 8px; border-radius: 20px; text-transform: uppercase; width: fit-content; }
.product-card h3 { font-size: 17px; font-weight: 700; color: var(--dark); }
.product-card .tagline { font-size: 13px; color: var(--secondary); line-height: 1.4; }
.product-card .price { font-size: 13px; color: var(--dark); margin-top: auto; }
.product-card .monthly { font-size: 11px; color: var(--secondary); }
.product-card .card-links { display: flex; gap: 12px; margin-top: 8px; }
.product-card .card-links a { font-size: 13px; color: var(--blue); }

/* CTA Buttons */
.btn-primary {
  display: inline-block;
  background: var(--blue);
  color: #fff;
  font-size: 15px;
  font-weight: 400;
  padding: 10px 22px;
  border-radius: 980px;
  border: none;
  cursor: pointer;
  transition: background 0.15s;
  text-decoration: none;
}
.btn-primary:hover { background: var(--blue-hover); color: #fff; text-decoration: none; }
.btn-ghost {
  display: inline-block;
  background: transparent;
  color: var(--blue);
  font-size: 15px;
  font-weight: 400;
  padding: 10px 22px;
  border-radius: 980px;
  border: 1.5px solid var(--blue);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  text-decoration: none;
}
.btn-ghost:hover { background: var(--blue); color: #fff; text-decoration: none; }

/* Help cards */
.help-card {
  flex: 0 0 220px;
  background: var(--light-bg);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  min-height: 200px;
  display: flex; flex-direction: column; gap: 8px;
}
.help-card h3 { font-size: 19px; font-weight: 700; }
.help-card p { font-size: 14px; color: var(--secondary); line-height: 1.5; }
.help-card a { font-size: 13px; color: var(--blue); margin-top: auto; }

/* Store difference */
.diff-card {
  flex: 0 0 220px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  display: flex; flex-direction: column; gap: 8px;
}
.diff-icon { font-size: 28px; margin-bottom: 6px; }
.diff-card h3 { font-size: 17px; font-weight: 700; }
.diff-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }

/* Brand collab */
.brand-collab-section {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  padding: 60px 22px;
  text-align: center;
  color: #fff;
}
.brand-collab-section h2 { font-size: 40px; font-weight: 700; letter-spacing: -1px; }
.brand-collab-section p { font-size: 17px; opacity: 0.8; margin-top: 8px; }

/* Audio promo strip */
.audio-promo { font-size: 13px; color: var(--secondary); margin-bottom: 12px; }
.audio-promo a { color: var(--blue); }

/* Savings carousel card */
.savings-card {
  flex: 0 0 280px;
  background: var(--light-bg);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  min-height: 160px;
  display: flex; flex-direction: column; gap: 8px;
}
.savings-card h3 { font-size: 17px; font-weight: 700; }
.savings-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.savings-card a { font-size: 13px; color: var(--blue); margin-top: auto; }

/* Quick links */
.quick-links-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  padding: 40px 22px;
  border-top: 1px solid var(--border);
  background: var(--light-bg);
}
.quick-link-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 980px;
  padding: 10px 20px;
  font-size: 14px;
  color: var(--blue);
  font-weight: 400;
  cursor: pointer;
  transition: box-shadow 0.15s;
  text-decoration: none;
}
.quick-link-btn:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.1); text-decoration: none; }

/* Footer */
.site-footer {
  background: var(--light-bg);
  border-top: 1px solid var(--border);
  padding: 32px 22px 24px;
}
.footer-inner { max-width: 980px; margin: 0 auto; }
.footer-legal { font-size: 12px; color: var(--secondary); border-bottom: 1px solid var(--border); padding-bottom: 16px; margin-bottom: 20px; line-height: 1.6; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 24px 16px; margin-bottom: 24px; }
.footer-col h4 { font-size: 13px; font-weight: 600; color: var(--dark); margin-bottom: 10px; cursor: pointer; display: flex; align-items: center; justify-content: space-between; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 6px; }
.footer-col ul li a { font-size: 12px; color: var(--secondary); }
.footer-col ul li a:hover { color: var(--dark); text-decoration: none; }
.footer-bottom { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; justify-content: space-between; }
.footer-copyright { font-size: 12px; color: var(--secondary); }
.footer-links { display: flex; gap: 16px; }
.footer-links a { font-size: 12px; color: var(--secondary); }

/* Full-width colored bg for sections */
.bg-light { background: var(--light-bg); }
.bg-white { background: var(--white); }

/* Page Hero */
.page-hero {
  text-align: center;
  padding: 64px 22px 48px;
  background: var(--light-bg);
  border-bottom: 1px solid var(--border);
}
.page-hero h1 { font-size: 52px; font-weight: 700; letter-spacing: -2px; line-height: 1; }
.page-hero p { font-size: 19px; color: var(--secondary); margin-top: 10px; }
.page-hero-btns { display: flex; gap: 12px; justify-content: center; margin-top: 20px; flex-wrap: wrap; }

/* Section Nav (sticky tabs) */
.section-nav {
  position: sticky;
  top: 44px;
  z-index: 90;
  background: rgba(255,255,255,0.9);
  backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border);
}
.section-nav-inner {
  max-width: 980px;
  margin: 0 auto;
  display: flex;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 0 16px;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav-inner a {
  display: block;
  white-space: nowrap;
  padding: 12px 16px;
  font-size: 13px;
  color: var(--secondary);
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
  text-decoration: none;
}
.section-nav-inner a:hover, .section-nav-inner a.active { color: var(--dark); border-bottom-color: var(--dark); text-decoration: none; }

/* Product Grid (homepage) */
.product-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; max-width: 1200px; margin: 0 auto; padding: 16px 22px; }
@media (max-width: 768px) { .product-grid { grid-template-columns: 1fr; } }
.product-hero-tile {
  background: var(--light-bg);
  border-radius: var(--card-radius);
  padding: 40px 32px 32px;
  display: flex; flex-direction: column;
  align-items: center;
  text-align: center;
  min-height: 360px;
  position: relative;
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.product-hero-tile:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.12); }
.product-hero-tile.tile-phone { background: linear-gradient(145deg, #e8eaf6 0%, #c5cae9 100%); }
.product-hero-tile.tile-neo { background: linear-gradient(145deg, #e8f5e9 0%, #c8e6c9 100%); }
.product-hero-tile.tile-tablet { background: linear-gradient(145deg, #e3f2fd 0%, #bbdefb 100%); }
.product-hero-tile.tile-laptop-pro { background: linear-gradient(145deg, #fce4ec 0%, #f8bbd9 100%); }
.product-hero-tile.tile-earbuds { background: linear-gradient(145deg, #fff3e0 0%, #ffe0b2 100%); }
.product-hero-tile.tile-trade { background: linear-gradient(145deg, #e0f7fa 0%, #b2ebf2 100%); }
.product-hero-tile-img { flex: 1; display: flex; align-items: center; justify-content: center; margin-bottom: 16px; }
.product-hero-tile-img img { max-height: 200px; max-width: 100%; object-fit: contain; }
.product-hero-tile h2 { font-size: 26px; font-weight: 700; letter-spacing: -0.5px; color: var(--dark); }
.product-hero-tile .tagline { font-size: 14px; color: var(--secondary); margin-top: 4px; line-height: 1.4; }
.tile-btns { display: flex; gap: 12px; margin-top: 16px; justify-content: center; flex-wrap: wrap; }
.tile-btns a.learn { font-size: 15px; color: var(--blue); }
.tile-btns a.buy { font-size: 15px; color: var(--blue); }
.tile-divider { color: var(--border); }

/* Entertainment tabs */
.entertainment-section { background: var(--dark); padding: 60px 22px; color: #fff; }
.entertainment-inner { max-width: 1200px; margin: 0 auto; }
.entertainment-inner h2 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; margin-bottom: 24px; }
.ent-tabs { display: flex; gap: 4px; margin-bottom: 32px; flex-wrap: wrap; }
.ent-tab {
  padding: 8px 20px;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  color: rgba(255,255,255,0.6);
  background: transparent;
  border: 1px solid rgba(255,255,255,0.2);
  transition: background 0.15s, color 0.15s;
}
.ent-tab:hover { color: #fff; background: rgba(255,255,255,0.1); }
.ent-tab.active { background: #fff; color: var(--dark); border-color: #fff; }
.ent-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
.ent-card {
  background: rgba(255,255,255,0.08);
  border-radius: var(--card-radius);
  padding: 20px;
  display: flex; flex-direction: column; gap: 8px;
}
.ent-card-thumb { height: 100px; background: rgba(255,255,255,0.1); border-radius: 10px; margin-bottom: 8px; display: flex; align-items: center; justify-content: center; font-size: 32px; }
.ent-card h4 { font-size: 15px; font-weight: 600; }
.ent-card p { font-size: 12px; color: rgba(255,255,255,0.5); }
.ent-card a { font-size: 13px; color: #6eb6ff; margin-top: auto; }

/* Product icon bar */
.product-icon-bar { background: var(--white); border-bottom: 1px solid var(--border); padding: 16px 0; overflow-x: auto; scrollbar-width: none; }
.product-icon-bar::-webkit-scrollbar { display: none; }
.product-icon-bar-inner { display: flex; gap: 0; max-width: 980px; margin: 0 auto; padding: 0 16px; }
.product-icon-item { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 8px 16px; text-decoration: none; flex: 0 0 auto; }
.product-icon-item span { font-size: 12px; color: var(--secondary); white-space: nowrap; }
.product-icon-item:hover span { color: var(--blue); text-decoration: none; }
.product-icon-item svg, .product-icon-item .icon-emoji { font-size: 22px; width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; }

/* Store hero */
.store-hero { padding: 40px 22px 32px; max-width: 980px; margin: 0 auto; }
.store-hero h1 { font-size: 48px; font-weight: 700; letter-spacing: -2px; }
.store-hero p { font-size: 19px; color: var(--secondary); margin-top: 6px; }
.store-hero-btns { display: flex; gap: 12px; margin-top: 20px; flex-wrap: wrap; }

/* Responsive tweaks */
@media (max-width: 768px) {
  .product-grid { grid-template-columns: 1fr; }
  .carousel-btn.prev { left: 4px; }
  .carousel-btn.next { right: 4px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col ul { display: none; }
  .footer-col ul.open { display: flex; }
  .footer-col h4 .chevron::after { content: '+'; font-size: 16px; color: var(--secondary); }
  .footer-col.open h4 .chevron::after { content: '−'; }
  .global-nav-inner { overflow-x: auto; }
  .nav-links { gap: 0; }
  .nav-links a { padding: 4px 6px; font-size: 12px; }
  .page-hero h1 { font-size: 36px; }
  .product-hero-tile h2 { font-size: 22px; }
}

/* Shopping guide cards */
.guide-card {
  flex: 0 0 240px;
  background: var(--light-bg);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  min-height: 180px;
  display: flex; flex-direction: column; gap: 8px;
}
.guide-card h3 { font-size: 17px; font-weight: 700; }
.guide-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.guide-card a { font-size: 13px; color: var(--blue); margin-top: auto; }

/* Ways to save cards */
.save-card {
  flex: 0 0 240px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  min-height: 160px;
  display: flex; flex-direction: column; gap: 8px;
}
.save-card h3 { font-size: 17px; font-weight: 700; }
.save-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.save-card a { font-size: 13px; color: var(--blue); margin-top: auto; }

/* Setup support section */
.setup-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.setup-card { background: var(--light-bg); border-radius: var(--card-radius); padding: 28px 24px; }
.setup-card h3 { font-size: 17px; font-weight: 700; margin-bottom: 6px; }
.setup-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.setup-card a { font-size: 13px; color: var(--blue); display: block; margin-top: 8px; }

/* Special stores grid */
.special-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.special-card { background: var(--dark); color: #fff; border-radius: var(--card-radius); padding: 28px 24px; }
.special-card h3 { font-size: 17px; font-weight: 700; margin-bottom: 6px; }
.special-card p { font-size: 13px; color: rgba(255,255,255,0.6); line-height: 1.5; }
.special-card a { font-size: 13px; color: #6eb6ff; display: block; margin-top: 8px; }

/* Carousel JS utility */
.no-scroll-x { overflow: hidden; }

