/* Orchard — Shared Styles */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --dark: #1d1d1f;
  --light-bg: #f5f5f7;
  --secondary: #6e6e73;
  --blue: #0066cc;
  --blue-hover: #004499;
  --white: #ffffff;
  --border: #d2d2d7;
  --card-radius: 18px;
  --font: -apple-system, "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
}

html { scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--dark); background: var(--white); -webkit-font-smoothing: antialiased; }

a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; color: var(--blue-hover); }

/* Ribbon Banner */
.ribbon-banner {
  background: var(--light-bg);
  text-align: center;
  padding: 10px 16px;
  font-size: 13px;
  color: var(--dark);
  border-bottom: 1px solid var(--border);
}
.ribbon-banner a { color: var(--blue); font-weight: 400; }

/* Global Nav */
.global-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border);
}
.global-nav-inner {
  max-width: 980px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 44px;
  padding: 0 16px;
  gap: 0;
}
.nav-logo { font-size: 20px; font-weight: 300; letter-spacing: -0.5px; color: var(--dark); flex: 0 0 auto; margin-right: auto; }
.nav-logo span { font-weight: 600; }
.nav-links { display: flex; gap: 4px; list-style: none; align-items: center; margin: 0 auto; }
.nav-links a { font-size: 13px; color: var(--dark); padding: 4px 8px; border-radius: 6px; transition: background 0.15s; white-space: nowrap; }
.nav-links a:hover { background: var(--light-bg); text-decoration: none; }
.nav-links a.active { font-weight: 600; }
.nav-actions { display: flex; gap: 8px; align-items: center; margin-left: auto; }
.nav-actions a { font-size: 13px; color: var(--dark); }

/* Section */
.section { padding: 60px 22px; max-width: 1200px; margin: 0 auto; }
.section-sm { padding: 40px 22px; max-width: 1200px; margin: 0 auto; }

.section-header { margin-bottom: 32px; }
.section-header h2 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; color: var(--dark); line-height: 1.1; }
.section-header p { font-size: 17px; color: var(--secondary); margin-top: 6px; }

/* Carousel */
.carousel-wrapper { position: relative; }
.carousel-track-outer { overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 16px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 50%;
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  z-index: 10;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  transition: box-shadow 0.15s, background 0.15s;
  color: var(--dark);
}
.carousel-btn:hover { background: var(--light-bg); box-shadow: 0 4px 16px rgba(0,0,0,0.16); }
.carousel-btn.prev { left: -20px; }
.carousel-btn.next { right: -20px; }
.carousel-btn svg { width: 16px; height: 16px; pointer-events: none; }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }

