.ent-card-thumb { height: 100px; background: rgba(255,255,255,0.1); border-radius: 10px; margin-bottom: 8px; display: flex; align-items: center; justify-content: center; font-size: 32px; }
.ent-card h4 { font-size: 15px; font-weight: 600; }
.ent-card p { font-size: 12px; color: rgba(255,255,255,0.5); }
.ent-card a { font-size: 13px; color: #6eb6ff; margin-top: auto; }

/* Product icon bar */
.product-icon-bar { background: var(--white); border-bottom: 1px solid var(--border); padding: 16px 0; overflow-x: auto; scrollbar-width: none; }
.product-icon-bar::-webkit-scrollbar { display: none; }
.product-icon-bar-inner { display: flex; gap: 0; max-width: 980px; margin: 0 auto; padding: 0 16px; }
.product-icon-item { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 8px 16px; text-decoration: none; flex: 0 0 auto; }
.product-icon-item span { font-size: 12px; color: var(--secondary); white-space: nowrap; }
.product-icon-item:hover span { color: var(--blue); text-decoration: none; }
.product-icon-item svg, .product-icon-item .icon-emoji { font-size: 22px; width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; }

/* Store hero */
.store-hero { padding: 40px 22px 32px; max-width: 980px; margin: 0 auto; }
.store-hero h1 { font-size: 48px; font-weight: 700; letter-spacing: -2px; }
.store-hero p { font-size: 19px; color: var(--secondary); margin-top: 6px; }
.store-hero-btns { display: flex; gap: 12px; margin-top: 20px; flex-wrap: wrap; }

/* Responsive tweaks */
@media (max-width: 768px) {
  .product-grid { grid-template-columns: 1fr; }
  .carousel-btn.prev { left: 4px; }
  .carousel-btn.next { right: 4px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col ul { display: none; }
  .footer-col ul.open { display: flex; }
  .footer-col h4 .chevron::after { content: '+'; font-size: 16px; color: var(--secondary); }
  .footer-col.open h4 .chevron::after { content: '−'; }
  .global-nav-inner { overflow-x: auto; }
  .nav-links { gap: 0; }
  .nav-links a { padding: 4px 6px; font-size: 12px; }
  .page-hero h1 { font-size: 36px; }
  .product-hero-tile h2 { font-size: 22px; }
}

/* Shopping guide cards */
.guide-card {
  flex: 0 0 240px;
  background: var(--light-bg);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  min-height: 180px;
  display: flex; flex-direction: column; gap: 8px;
}
.guide-card h3 { font-size: 17px; font-weight: 700; }
.guide-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.guide-card a { font-size: 13px; color: var(--blue); margin-top: auto; }

/* Ways to save cards */
.save-card {
  flex: 0 0 240px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  padding: 28px 24px;
  min-height: 160px;
  display: flex; flex-direction: column; gap: 8px;
}
.save-card h3 { font-size: 17px; font-weight: 700; }
.save-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.save-card a { font-size: 13px; color: var(--blue); margin-top: auto; }

/* Setup support section */
.setup-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.setup-card { background: var(--light-bg); border-radius: var(--card-radius); padding: 28px 24px; }
.setup-card h3 { font-size: 17px; font-weight: 700; margin-bottom: 6px; }
.setup-card p { font-size: 13px; color: var(--secondary); line-height: 1.5; }
.setup-card a { font-size: 13px; color: var(--blue); display: block; margin-top: 8px; }

/* Special stores grid */
.special-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.special-card { background: var(--dark); color: #fff; border-radius: var(--card-radius); padding: 28px 24px; }
.special-card h3 { font-size: 17px; font-weight: 700; margin-bottom: 6px; }
.special-card p { font-size: 13px; color: rgba(255,255,255,0.6); line-height: 1.5; }
.special-card a { font-size: 13px; color: #6eb6ff; display: block; margin-top: 8px; }

/* Carousel JS utility */
.no-scroll-x { overflow: hidden; }
